read.script:
const rows = document.querySelectorAll('tr.athing');
if (!rows || rows.length === 0) {
  throw new Error('Missing expected Hacker News front page stories');
}
const items = [];
for (const tr of rows) {
  const id = tr.id;
  const titleEl = tr.querySelector('.titleline > a');
  const title = titleEl ? titleEl.innerText.trim() : '';
  const url = titleEl ? titleEl.href : '';
  const subtextTr = tr.nextElementSibling;
  const subtext = subtextTr ? subtextTr.querySelector('.subtext') : null;
  const commentsA = subtext ? subtext.querySelector('a[href*="item?id="]:last-child') : null;
  const commentsUrl = (commentsA && commentsA.getAttribute('href') && commentsA.getAttribute('href').includes('item?id='))
    ? commentsA.href
    : `https://news.ycombinator.com/item?id=${id}`;
  items.push({ id, title, url, commentsUrl });
}
return items;

const hasExpectedStructure = Boolean(
  document.querySelector('.fatitem') ||
  document.querySelector('.comment-tree') ||
  document.querySelector('tr.athing')
);
if (!hasExpectedStructure) {
  throw new Error(`Expected HN comment page structure not found for item ${input.story.id}`);
}
const commentRows = Array.from(document.querySelectorAll('tr.athing.comtr'));
const topLevel = [];
for (const tr of commentRows) {
  const indentImg = tr.querySelector('td.ind img');
  const indentWidth = indentImg ? parseInt(indentImg.getAttribute('width') || '0', 10) : 0;
  if (indentWidth !== 0) continue;

  if (tr.classList.contains('noshow') || tr.classList.contains('coll') || tr.classList.contains('dead')) continue;
  if (tr.style.display === 'none') continue;

  const commtextEl = tr.querySelector('.commtext');
  if (!commtextEl) continue;
  if (commtextEl.classList.contains('dead')) continue;

  const fullText = (commtextEl.innerText || commtextEl.textContent || '').trim();
  if (!fullText) continue;
  const lower = fullText.toLowerCase();
  if (lower === '[deleted]' || lower === '[dead]' || lower === '[flagged]') continue;

  const id = tr.id;
  const permalinkA = tr.querySelector('.age a');
  let permalink = '';
  if (permalinkA && permalinkA.getAttribute('href')) {
    const href = permalinkA.getAttribute('href');
    permalink = href.startsWith('http') ? href : `https://news.ycombinator.com/${href.replace(/^\//, '')}`;
  } else {
    permalink = `https://news.ycombinator.com/item?id=${id}`;
  }

  const maxChars = 1000;
  const usedExcerpt = fullText.length > maxChars;
  const textForModel = usedExcerpt ? fullText.slice(0, maxChars) + '...' : fullText;

  topLevel.push({
    permalink,
    fullText,
    textForModel,
    usedExcerpt
  });
  if (topLevel.length === 3) break;
}
return {
  storyId: input.story.id,
  storyTitle: input.story.title,
  storyUrl: input.story.url,
  commentsUrl: input.story.commentsUrl,
  comments: topLevel
};

const flat = [];
const stories = input.storiesWithComments || [];
for (let sIdx = 0; sIdx < stories.length; sIdx++) {
  const story = stories[sIdx];
  const comments = story.comments || [];
  for (let cIdx = 0; cIdx < comments.length; cIdx++) {
    const c = comments[cIdx];
    flat.push({
      storyIndex: sIdx,
      commentIndex: cIdx,
      permalink: c.permalink,
      fullText: c.fullText,
      textForModel: c.textForModel,
      usedExcerpt: c.usedExcerpt
    });
  }
}
return flat;

return {
  storyIndex: input.commentItem.storyIndex,
  commentIndex: input.commentItem.commentIndex,
  permalink: input.commentItem.permalink,
  fullText: input.commentItem.fullText,
  judgment: input.sentiment,
  judgmentUsedExcerpt: input.commentItem.usedExcerpt
};

const stories = input.storiesWithComments || [];
const judged = input.allJudgedComments || [];
return stories.map((story, sIdx) => {
  const storyComments = judged
    .filter(c => c.storyIndex === sIdx)
    .sort((a, b) => a.commentIndex - b.commentIndex)
    .map(c => ({
      permalink: c.permalink,
      fullText: c.fullText,
      judgment: c.judgment,
      judgmentUsedExcerpt: c.judgmentUsedExcerpt
    }));
  return {
    title: story.storyTitle,
    url: story.storyUrl,
    commentsUrl: story.commentsUrl,
    comments: storyComments
  };
});
